        vm.assume(adr != address(0));
        vm.assume(adr != address(c));

        // Deal ETH to the contract
        vm.deal(address(c), 1 ether);

        // Record Owner's balance before Command
        address owner = c.Owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Execute Command with msg.value = amount (bounded to safe value)
        amount = bound(amount, 0, address(c).balance);

        // Record the return value of the external call
        (bool success, ) = adr.call{gas: 100000}("");

        // Execute the Command
        vm.prank(owner);
        c.Command(adr, data);

        // Check: Owner's balance change equals amount if the external call succeeded (non-reverting)
        // If the call reverted (success == false), the amount was returned to contract, so Owner balance unchanged
        uint256 ownerBalanceAfter = owner.balance;
        uint256 expectedChange = success ? amount : 0;

        assertTrue(ownerBalanceAfter == ownerBalanceBefore + expectedChange, "Owner balance should increase by msg.value only if external call succeeds");
    }
}

