        vm.assume(adr != address(0) && adr != address(c) && adr != address(this));
        vm.assume(data.length > 0);
        vm.assume(value <= address(c).balance);

        // Record initial owner balance
        address owner = c.Owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // First call to Command with non-empty data
        vm.prank(owner);
        (bool success1, ) = address(c).call{value: value}(abi.encodeWithSignature("Command(address,bytes)", adr, data));

        // Record state after first call
        uint256 ownerBalanceAfter1 = owner.balance;

        // Second call to Command with same non-empty data
